import re
from pathlib import Path

from ci.praktika.info import Info
from ci.praktika.utils import Shell

FILE_WITH_VERSION_PATH = "./cmake/autogenerated_versions.txt"

# Canonical layout of cmake/autogenerated_versions.txt as committed to the repo.
VERSIONS_TEMPLATE = """\
# This variables autochanged by ci/jobs/create_release.py:

# NOTE: VERSION_REVISION has nothing common with DBMS_TCP_PROTOCOL_VERSION,
# only DBMS_TCP_PROTOCOL_VERSION should be incremented on protocol changes.
SET(VERSION_REVISION {revision})
SET(VERSION_MAJOR {major})
SET(VERSION_MINOR {minor})
SET(VERSION_PATCH {patch})
SET(VERSION_GITHASH {githash})
SET(VERSION_DESCRIBE {describe})
SET(VERSION_STRING {string})
# end of autochange
"""


class VersionType:
    NEW = "new"
    TESTING = "testing"
    PRESTABLE = "prestable"
    STABLE = "stable"
    LTS = "lts"
    VALID = {NEW, TESTING, PRESTABLE, STABLE, LTS}


def _read_versions() -> dict:
    versions = {}
    for line in Path(FILE_WITH_VERSION_PATH).read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line.startswith("SET("):
            continue
        name, value = line[4:-1].split(maxsplit=1)
        name = name.removeprefix("VERSION_").lower()
        try:
            value = int(value)
        except ValueError:
            pass
        versions[name] = value
    return versions


class CHVersion:
    """The ClickHouse version.

    As an instance it is a mutable version model used to bump and render the
    release version. Its class methods read and write
    `cmake/autogenerated_versions.txt` and derive the CI build version.
    """

    def __init__(self, major, minor, patch, revision, tweak=1):
        self.major = int(major)
        self.minor = int(minor)
        self.patch = int(patch)
        self.revision = int(revision)
        self.tweak = int(tweak)
        self.version_type = ""

    def bump(self) -> "CHVersion":
        """Bump minor version (or wrap to next major when minor reaches 12)."""
        if self.minor < 12:
            self.minor += 1
        else:
            self.major += 1
            self.minor = 1
        self.revision += 1
        self.patch = 1
        self.tweak = 1
        return self

    def bump_patch(self) -> "CHVersion":
        self.revision += 1
        self.patch += 1
        self.tweak = 1
        return self

    def reset_tweak(self) -> "CHVersion":
        self.tweak = 1
        return self

    def with_description(self, version_type: str) -> "CHVersion":
        if version_type not in VersionType.VALID:
            raise ValueError(f"version type {version_type!r} not in {VersionType.VALID}")
        self.version_type = version_type
        return self

    def get_stable_release_type(self) -> str:
        return VersionType.LTS if self.minor % 5 == 3 else VersionType.STABLE

    def is_older_release_than(self, other: "CHVersion") -> bool:
        """Whether this is an older release than `other`, by release triple
        (major, minor, patch). The tweak is a within-patch commit count and does
        not define a newer release."""
        return (self.major, self.minor, self.patch) < (
            other.major,
            other.minor,
            other.patch,
        )

    @property
    def string(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}.{self.tweak}"

    @property
    def describe(self) -> str:
        return f"v{self.string}-{self.version_type}" if self.version_type else ""

    def as_dict(self) -> dict:
        return {
            "revision": self.revision,
            "major": self.major,
            "minor": self.minor,
            "patch": self.patch,
            "tweak": self.tweak,
            "githash": Shell.get_output("git rev-parse HEAD") or "0" * 40,
            "describe": self.describe,
            "string": self.string,
        }

    # --- reading / writing cmake/autogenerated_versions.txt ------------------

    @classmethod
    def get_release_version_as_dict(cls):
        versions = _read_versions()
        return {
            "major": versions["major"],
            "minor": versions["minor"],
            "patch": versions["patch"],
            "revision": versions["revision"],
            "githash": versions["githash"],
            "describe": versions["describe"],
            "string": versions["string"],
        }

    @classmethod
    def _get_current_version_from_rev_list(cls) -> dict:
        """Version from the file with the tweak set to the commit count since the
        file's githash (`git rev-list --count`).

        Unlike `get_current_version_as_dict`, this does NOT consult the CI `Info`
        context (no `pr_number` / branch / sha), so it touches neither
        `_Environment` nor any CI state. That makes it safe to call while checked
        out to an arbitrary release commit — where the checked-out praktika schema
        may differ from the running env — which is why the release process uses it.
        """
        version = cls.get_release_version_as_dict()
        try:
            tweak = int(
                Shell.get_output(
                    f"git rev-list --count --first-parent {version['githash']}..HEAD",
                    verbose=True,
                )
            )
        except (ValueError, Exception):
            # Shallow checkout or other error
            tweak = 1
        version["tweak"] = tweak
        version["string"] = (
            f'{version["major"]}.{version["minor"]}.{version["patch"]}.{tweak}'
        )
        return version

    @classmethod
    def get_current_version_as_dict(cls):
        """Version stamped into the binary during a CI build.

        In a PR the tweak is pinned to 1 and git rev-list is NOT consulted: the
        merge commit's count diverges across close/reopen for the same HEAD,
        which would upload diverging version strings to one artifact prefix. On
        master / release branches the tweak is the real commit count (via
        `_get_current_version_from_rev_list`) and the type is derived from the
        branch. githash is always the CI sha.
        """
        info = Info()
        version_type = "testing"
        if info.pr_number != 0:
            version = cls.get_release_version_as_dict()
            version["tweak"] = 1
            version["string"] = (
                f'{version["major"]}.{version["minor"]}.{version["patch"]}.1'
            )
        else:
            version = cls._get_current_version_from_rev_list()
            if bool(
                re.match(r"^\d{2}\.\d+$", info.git_branch.removeprefix("release/"))
            ):
                version_type = "lts" if version["minor"] % 5 == 3 else "stable"
        version["githash"] = info.sha
        version["describe"] = f'v{version["string"]}-{version_type}'
        return version

    @classmethod
    def current(cls) -> "CHVersion":
        """The release version from `cmake/autogenerated_versions.txt` with the
        tweak from the commit count since the file's githash. Uses
        `_get_current_version_from_rev_list` (no CI `Info`/`_Environment`), so it
        is safe inside a checkout of an arbitrary release commit."""
        d = cls._get_current_version_from_rev_list()
        return cls(d["major"], d["minor"], d["patch"], d["revision"], d["tweak"])

    @staticmethod
    def _write_version_file(version_dict: dict) -> None:
        Path(FILE_WITH_VERSION_PATH).write_text(
            VERSIONS_TEMPLATE.format_map(version_dict), encoding="utf-8"
        )

    @classmethod
    def set_binary_version(cls, version_dict=None):
        cls._write_version_file(version_dict or cls.get_current_version_as_dict())

    @staticmethod
    def store_version_data_in_ci_pipeline(version):
        print(f"Store version in pipeline kv data: [version={version}]")
        Info().store_kv_data("version", version)


def update_cmake_version(version: CHVersion, preserve_sha: bool = False) -> None:
    version_dict = version.as_dict()
    if preserve_sha:
        version_dict["githash"] = _read_versions().get("githash", "0" * 40)
    CHVersion._write_version_file(version_dict)


if __name__ == "__main__":
    # test;
    print(CHVersion.get_current_version_as_dict())
